B.a0y=new A.am(B.cw,["Seviye 2","12 G\u0131da","0.40 Arpa / sn","\xc7ay\u0131r Karosu"],t.w)
B.Yl=s(["K\u0131m\u0131z Ota\u011f\u0131 a\xe7\u0131lmadan \xf6nce arpa stoklamak h\u0131zl\u0131 k\u0131m\u0131z \xfcretimini garanti eder."],t.s)
